using System.Buffers.Binary;
using EnbNext.Net7.World;
using EnbNext.Presentation;
using EnbNext.Protocol.Net;

namespace EnbNext.Net7.Tests;

public sealed class Net7ShipBuffWireRegressionTests
{
    // Incoming 0x001B deltas from the user's ordinary 2026-09-05 capture,
    // frames 74/76, reliable sequences 46/47. Not generated by our encoder.
    private const string Explosive = "010200000000400200120000920010004578706C6F736976652052657369737479DF201D02200014000000";
    private const string Regenerate = "01020000000040000022000092001100526567656E657261746520456E65726779A261211D";
    private const uint ShipId = 0x40011E2D;

    [Fact]
    public void ShipIdsAndChildIndexesFollowRetailRegistrationNotConstructionOrder()
    {
        var schema = new Net7AuxDataSchemaCatalog().CreateObjectSchema(1)!;
        Assert.Equal(new[]
        {
            "ShipAuxData.VisibleQuadrantDamagePercent", "ShipAuxData.DamageSpot",
            "ShipAuxData.DamageLine", "ShipAuxData.DamageBlotch", "ShipAuxData.Legos",
            "ShipAuxData.BuffArray", "ShipAuxData.TradeMoney",
        }, schema.Root.Children.Skip(37).Take(7).Select(p => p.Path));
        Assert.Equal("ShipAuxData.Legos", schema.Resolve(1254).Path);
        Assert.Equal("ShipAuxData.BuffArray", schema.Resolve(1347).Path);
        Assert.Equal(42, schema.Resolve(1347).ChildIndex);
        Assert.Equal("ShipAuxData.BuffArray.0.BuffRemovalTime", schema.Resolve(1352).Path);
        Assert.Equal("ShipAuxData.TradeMoney", schema.Resolve(1888).Path);
        Assert.Equal(43, schema.Resolve(1888).ChildIndex);
        Assert.Equal("ShipAuxData.BaseStats", schema.Resolve(1889).Path);
    }

    [Fact]
    public void RecordedItemBuffPacketsReachDetachedHudWithTheirActualSlotsAndTimes()
    {
        var world = CreateWorld();
        var builder = new EnbPresentationSnapshotBuilder();
        Assert.True(world.Apply(PacketFor(Explosive), 1000).PacketMaterialized);
        var first = builder.Build(world, null, 1000).Hud.Buffs;
        Assert.Equal("Explosive Resist", Assert.Single(first).Type);
        Assert.True(world.Apply(PacketFor(Regenerate), 1001).PacketMaterialized);
        var buffs = builder.Build(world, null, 1001).Hud.Buffs;
        Assert.Collection(buffs,
            buff => { Assert.Equal(0, buff.Slot); Assert.Equal("Explosive Resist", buff.Type); Assert.Equal(0x1D20DF79L, buff.RemovalTime); },
            buff => { Assert.Equal(1, buff.Slot); Assert.Equal("Regenerate Energy", buff.Type); Assert.Equal(0x1D2161A2L, buff.RemovalTime); });
        Assert.All(buffs, buff => Assert.True(buff.IsVisible(1001)));
        Assert.True(buffs[0].IsVisible(buffs[0].RemovalTime));
        Assert.False(buffs[0].IsVisible(buffs[0].RemovalTime + 1));
        Assert.Single(first); // A subsequent update cannot mutate the published snapshot.

        var ship = world.Objects.FindFirst(ShipId)!.AuxData!;
        Assert.Equal(20, Assert.IsType<int>(ship.Properties.Single(p => p.Path == "ShipAuxData.CurrentStats.ResistExplosive").Value));
        Assert.Null(ship.Resolve(1254).Value);
        Assert.Equal(0, ship.Resolve(1254).State); // Buff payload must not touch Legos.
        Assert.Null(ship.Resolve(1888).Value);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void ShortBuffUpdateRetainsCompletedTypeButNeverInventsRemovalTime(bool append)
    {
        var world = CreateWorld();
        world.Apply(PacketFor(Explosive), 1000);
        byte[] valid = Convert.FromHexString(Regenerate);
        byte[] malformed = append ? [.. valid, 0xFF] : valid[..^1];
        world.Apply(PacketFor(malformed), 1001);
        var buffs = new EnbPresentationSnapshotBuilder().Build(world, null, 1001).Hud.Buffs;
        Assert.Equal("Explosive Resist", buffs[0].Type);
        Assert.Equal(2,buffs.Length);
        if(!append) Assert.Equal(0,buffs[1].RemovalTime);
        var ship = world.Objects.FindFirst(ShipId)!.AuxData!;
        var type=ship.Properties.Single(p => p.Path == "ShipAuxData.BuffArray.1.BuffType").Value;
        Assert.Equal("Regenerate Energy",Assert.IsType<Net7AuxDataString>(type).Text);
        var removal = ship.Properties.Single(p => p.Path == "ShipAuxData.BuffArray.1.BuffRemovalTime").Value;
        if (append) Assert.Equal(0x1D2161A2, Assert.IsType<Net7AuxDataTime>(removal).RelativeValue);
        else Assert.Null(removal);
        world.Apply(PacketFor(valid),1002);
        Assert.Equal(0x1D2161A2,Assert.IsType<Net7AuxDataTime>(ship.Properties.Single(p => p.Path == "ShipAuxData.BuffArray.1.BuffRemovalTime").Value).RelativeValue);
    }

    private static Net7WorldState CreateWorld()
    {
        var world = new Net7WorldState();
        world.MaterializeCreate(new Net7CreateUpdate(ShipId, 1, 0, 0, 0, 0, 0));
        world.SetLocalPlayerId(ShipId);
        return world;
    }

    private static Packet PacketFor(string hex) => PacketFor(Convert.FromHexString(hex));

    private static Packet PacketFor(byte[] delta)
    {
        byte[] envelope = new byte[6 + delta.Length];
        BinaryPrimitives.WriteUInt32LittleEndian(envelope, ShipId);
        BinaryPrimitives.WriteUInt16LittleEndian(envelope.AsSpan(4), checked((ushort)delta.Length));
        delta.CopyTo(envelope, 6);
        return Packet.ForOpcode(0x001B, envelope);
    }
}
